<nav class="{{ $classes }}" aria-label="{{ $ariaLabel }}"{!! $attributes !!}><ol class="cm-breadcrumbs__list">@foreach ($items as $index => $item)<li class="cm-breadcrumbs__item">@if (!$item['disabled'] && !$item['current'] && $item['href'] !== null)<a class="cm-breadcrumbs__link" href="{{ $item['href'] }}">{{ $item['label'] }}</a>@else<span class="cm-breadcrumbs__current@if ($item['disabled']) cm-breadcrumbs__current--disabled@endif"@if ($item['current']) aria-current="page"@endif>{{ $item['label'] }}</span>@endif@if ($index < count($items) - 1)<span class="cm-breadcrumbs__separator" aria-hidden="true">{{ $separator }}</span>@endif</li>@endforeach</ol></nav>
